package com.makemytrip.makemytrip.repositories; import com.makemytrip.makemytrip.models.Review; import org.springframework.data.mongodb.repository.MongoRepository; import java.util.List; public interface ReviewRepository extends MongoRepository<Review,String>{List<Review> findByStatus(Review.Status status); List<Review> findByTargetTypeAndTargetIdAndStatus(Review.TargetType type,String targetId,Review.Status status); boolean existsByUserIdAndBookingId(String userId,String bookingId);}
